[metadata] {"type": "create", "filePath": "/app/output/styles.css", "content": "/* OpenLearnHub Shared Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

:root {
  --primary: #0A0A23;
  --primary-light: #1A1A3E;
  --accent: #FEAC32;
  --accent-hover: #F0A020;
  --link: #002EAD;
  --link-hover: #001F7A;
  --bg: #ffffff;
  --bg-secondary: #F8F9FA;
  --bg-tertiary: #F0F1F3;
  --text: #1A1A2E;
  --text-secondary: #555770;
  --text-muted: #8E8EA0;
  --border: #E2E4E9;
  --border-light: #EDEEF2;
  --radius: 0.625rem;
  --radius-sm: 0.375rem;
  --radius-lg: 0.875rem;
  --shadow-sm: 0 1px 3px rgba(10,10,35,0.06);
  --shadow: 0 2px 8px rgba(10,10,35,0.08);
  --shadow-lg: 0 4px 20px rgba(10,10,35,0.10);
  --font: 'Inter', system-ui, -apple-system, sans-serif;
  --max-width: 1200px;
  --header-height: 56px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 16px; scroll-behavior: smooth; }

body {
  font-family: var(--font);
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
ul { list-style: none; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 1.25rem; }

/* ===== HEADER ===== */
.site-header {
  background: var(--primary);
  color: #fff;
  position: sticky;
  top: 0;
  z-index: 100;
  height: var(--header-height);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: var(--header-height);
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.25rem;
  gap: 1.5rem;
}

.logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 1.25rem;
  font-weight: 700;
  color: #fff;
  white-space: nowrap;
}

.logo-icon {
  width: 28px;
  height: 28px;
  background: var(--accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  color: var(--primary);
  font-size: 0.875rem;
}

.search-bar {
  flex: 1;
  max-width: 520px;
  position: relative;
}

.search-bar input {
  width: 100%;
  padding: 0.5rem 0.875rem 0.5rem 2.25rem;
  border-radius: 9999px;
  border: none;
  background: rgba(255,255,255,0.12);
  color: #fff;
  font-size: 0.8125rem;
  font-family: var(--font);
  outline: none;
  transition: background 0.2s;
}

.search-bar input::placeholder { color: rgba(255,255,255,0.55); }
.search-bar input:focus { background: rgba(255,255,255,0.18); }

.search-bar .search-icon {
  position: absolute;
  left: 0.75rem;
  top: 50%;
  transform: translateY(-50%);
  width: 16px;
  height: 16px;
  opacity: 0.55;
}

.header-nav { display: flex; align-items: center; gap: 1.5rem; }

.header-nav a {
  color: rgba(255,255,255,0.85);
  font-size: 0.875rem;
  font-weight: 500;
  transition: color 0.15s;
}

.header-nav a:hover { color: var(--accent); }

.nav-donate {
  background: var(--accent);
  color: var(--primary) !important;
  padding: 0.4rem 1rem;
  border-radius: 9999px;
  font-weight: 600 !important;
  font-size: 0.8125rem;
  transition: background 0.15s;
}

.nav-donate:hover { background: var(--accent-hover) !important; color: var(--primary) !important; }

/* Mobile hamburger */
.hamburger {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.375rem;
  color: #fff;
}

.hamburger svg { width: 24px; height: 24px; }

.mobile-nav {
  display: none;
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  background: var(--primary);
  padding: 1rem 1.25rem;
  flex-direction: column;
  gap: 0.75rem;
  z-index: 99;
  border-top: 1px solid rgba(255,255,255,0.1);
}

.mobile-nav.open { display: flex; }

.mobile-nav a {
  color: rgba(255,255,255,0.85);
  font-size: 1rem;
  font-weight: 500;
  padding: 0.5rem 0;
}

.mobile-nav .nav-donate {
  display: inline-block;
  text-align: center;
  padding: 0.6rem 1.25rem;
}

/* ===== BANNER ===== */
.site-banner {
  background: var(--primary-light);
  color: #fff;
  text-align: center;
  padding: 0.6rem 1rem;
  font-size: 0.875rem;
  font-weight: 500;
}

.site-banner a { color: var(--accent); text-decoration: underline; }

/* ===== HERO / FEATURED ARTICLE ===== */
.featured-section { padding: 2.5rem 0; }

.featured-card {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 2rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: #fff;
  box-shadow: var(--shadow-sm);
  transition: box-shadow 0.2s;
}

.featured-card:hover { box-shadow: var(--shadow); }

.featured-image {
  aspect-ratio: 16/10;
  background: #E8EAF0;
  position: relative;
  overflow: hidden;
}

.featured-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.featured-tag {
  position: absolute;
  top: 1rem;
  left: 1rem;
  background: var(--accent);
  color: var(--primary);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.25rem 0.625rem;
  border-radius: 9999px;
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.featured-content {
  padding: 2rem 2rem 2rem 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.featured-content .card-tag {
  display: inline-block;
  background: #FFF3DC;
  color: #B87A14;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.2rem 0.625rem;
  border-radius: 9999px;
  margin-bottom: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.featured-content .card-tag:hover { background: #FEE6B0; }

.featured-content h2 {
  font-size: 1.5rem;
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: 1rem;
  color: var(--text);
}

.featured-content h2 a:hover { color: var(--link); }

/* ===== SECTION TITLE ===== */
.section-title {
  font-size: 1.35rem;
  font-weight: 700;
  margin-bottom: 1.5rem;
  color: var(--text);
}

/* ===== ARTICLE GRID ===== */
.articles-section { padding: 0 0 3rem; }

.article-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
  margin-bottom: 2rem;
}

.article-card {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  background: #fff;
  box-shadow: var(--shadow-sm);
  transition: box-shadow 0.2s, transform 0.2s;
}

.article-card:hover {
  box-shadow: var(--shadow);
  transform: translateY(-2px);
}

.card-thumbnail {
  aspect-ratio: 16/10;
  background: #E8EAF0;
  overflow: hidden;
}

.card-thumbnail img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.card-body { padding: 1.125rem; }

.card-tag {
  display: inline-block;
  font-size: 0.6875rem;
  font-weight: 700;
  padding: 0.2rem 0.5rem;
  border-radius: 9999px;
  margin-bottom: 0.5rem;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  transition: opacity 0.15s;
}

.card-tag:hover { opacity: 0.8; }

.tag-ai { background: #FFF3DC; color: #B87A14; }
.tag-web { background: #E0F0FF; color: #1A6DB5; }
.tag-db { background: #E8F5E9; color: #2E7D32; }
.tag-es { background: #FFF0E0; color: #E65100; }
.tag-de { background: #F3E5F5; color: #7B1FA2; }
.tag-python { background: #E8F0FE; color: #1565C0; }
.tag-node { background: #E8F5E9; color: #2E7D32; }
.tag-sheets { background: #E8F5E9; color: #2E7D32; }
.tag-ai-auto { background: #FFF3DC; color: #B87A14; }

.card-title {
  font-size: 1.0625rem;
  font-weight: 600;
  line-height: 1.35;
  margin-bottom: 0.75rem;
  color: var(--text);
}

.card-title a:hover { color: var(--link); }

.card-meta {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.author-avatar {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: #D0D3DD;
  overflow: hidden;
  flex-shrink: 0;
}

.author-avatar img { width: 100%; height: 100%; object-fit: cover; }

.author-name {
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--text-secondary);
}

.card-time {
  font-size: 0.75rem;
  color: var(--text-muted);
  margin-left: auto;
}

/* ===== LOAD MORE ===== */
.load-more-wrap { text-align: center; }

.btn-load-more {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 2rem;
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: 9999px;
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
  font-family: var(--font);
  transition: all 0.15s;
}

.btn-load-more:hover { background: var(--bg-tertiary); border-color: #C8CAD4; }

/* ===== DONATION PAGE ===== */
.donation-hero {
  text-align: center;
  padding: 3rem 1.25rem;
  max-width: 720px;
  margin: 0 auto;
}

.donation-hero h1 {
  font-size: 2rem;
  font-weight: 800;
  margin-bottom: 1rem;
  color: var(--text);
}

.donation-hero p {
  font-size: 1.0625rem;
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: 1.5rem;
}

.amount-selector {
  display: flex;
  justify-content: center;
  gap: 0.75rem;
  margin-bottom: 1.25rem;
  flex-wrap: wrap;
}

.amount-btn {
  padding: 0.875rem 2.25rem;
  border: 2px solid var(--border);
  border-radius: var(--radius);
  background: #fff;
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text);
  cursor: pointer;
  font-family: var(--font);
  transition: all 0.15s;
}

.amount-btn:hover { border-color: var(--accent); }

.amount-btn.active {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--primary);
}

.donation-message {
  font-size: 1rem;
  color: var(--text-secondary);
  margin-bottom: 1.25rem;
  min-height: 1.5rem;
}

.btn-donate {
  display: inline-block;
  padding: 0.875rem 3rem;
  background: var(--accent);
  color: var(--primary);
  border: none;
  border-radius: 9999px;
  font-size: 1rem;
  font-weight: 700;
  cursor: pointer;
  font-family: var(--font);
  transition: background 0.15s;
}

.btn-donate:hover { background: var(--accent-hover); }

.donation-sub {
  font-size: 0.8125rem;
  color: var(--text-muted);
  margin-top: 0.5rem;
}

/* ===== SUPPORTER BENEFITS ===== */
.benefits-section,
.initiatives-section,
.achievements-section {
  padding: 2rem 0;
}

.benefits-section h2,
.initiatives-section h2,
.achievements-section h2,
.faq-section h2 {
  font-size: 1.35rem;
  font-weight: 700;
  margin-bottom: 1.25rem;
}

.benefits-list { display: grid; gap: 0.625rem; }

.benefits-list li {
  display: flex;
  align-items: flex-start;
  gap: 0.625rem;
  font-size: 1rem;
  color: var(--text);
}

.benefits-list li::before {
  content: '';
  width: 8px;
  height: 8px;
  background: var(--accent);
  border-radius: 50%;
  flex-shrink: 0;
  margin-top: 0.5rem;
}

.initiatives-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.75rem;
}

.initiative-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 1rem 1.25rem;
  background: var(--bg-secondary);
  border-radius: var(--radius);
  font-size: 0.9375rem;
  font-weight: 500;
}

.initiative-icon {
  width: 40px;
  height: 40px;
  background: #FFF3DC;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  color: var(--accent);
  flex-shrink: 0;
}

.achievements-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.75rem;
}

.achievement-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 1rem 1.25rem;
  background: var(--bg-secondary);
  border-radius: var(--radius);
  font-size: 0.9375rem;
  font-weight: 500;
}

.achievement-icon { font-size: 1.5rem; flex-shrink: 0; }

/* ===== FAQ ===== */
.faq-section { padding: 2rem 0 3rem; }

.faq-list { display: grid; gap: 0.5rem; }

.faq-item {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
}

.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 1rem 1.25rem;
  background: #fff;
  border: none;
  cursor: pointer;
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text);
  font-family: var(--font);
  text-align: left;
  transition: background 0.15s;
}

.faq-question:hover { background: var(--bg-secondary); }

.faq-question .faq-icon {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  transition: transform 0.2s;
  color: var(--text-muted);
}

.faq-item.open .faq-question .faq-icon { transform: rotate(180deg); }

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease-out;
}

.faq-item.open .faq-answer { max-height: 300px; }

.faq-answer-inner {
  padding: 0 1.25rem 1.25rem;
  font-size: 0.9375rem;
  color: var(--text-secondary);
  line-height: 1.7;
}

/* ===== LEARN PAGE ===== */
.learn-hero {
  padding: 2.5rem 0;
}

.learn-hero h1 {
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: 0.75rem;
}

.learn-hero p {
  font-size: 1.0625rem;
  color: var(--text-secondary);
  margin-bottom: 1rem;
}

.btn-signin {
  display: inline-block;
  padding: 0.625rem 1.5rem;
  background: var(--accent);
  color: var(--primary);
  border-radius: 9999px;
  font-weight: 600;
  font-size: 0.875rem;
  transition: background 0.15s;
}

.btn-signin:hover { background: var(--accent-hover); }

.curriculum-section { padding: 0 0 2.5rem; }

.curriculum-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.875rem;
}

.curriculum-card {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 1.25rem;
  background: var(--bg-secondary);
  border: 1px solid var(--border-light);
  border-radius: var(--radius);
  transition: box-shadow 0.15s, background 0.15s;
}

.curriculum-card:hover {
  background: #fff;
  box-shadow: var(--shadow);
}

.curriculum-icon {
  width: 48px;
  height: 48px;
  background: #FFF3DC;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.curriculum-icon svg { width: 24px; height: 24px; color: var(--accent); }

.curriculum-card h3 {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text);
}

.daily-challenge-section {
  padding: 2rem 0;
}

.challenge-box {
  background: var(--primary);
  color: #fff;
  padding: 2rem;
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
}

.challenge-box h2 {
  font-size: 1.35rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
}

.challenge-box p { color: rgba(255,255,255,0.75); }

.challenge-links {
  display: flex;
  gap: 0.75rem;
  flex-shrink: 0;
}

.btn-challenge {
  padding: 0.625rem 1.5rem;
  background: var(--accent);
  color: var(--primary);
  border-radius: 9999px;
  font-weight: 600;
  font-size: 0.875rem;
  white-space: nowrap;
  transition: background 0.15s;
}

.btn-challenge:hover { background: var(--accent-hover); }

.btn-challenge-ghost {
  padding: 0.625rem 1.5rem;
  border: 1px solid rgba(255,255,255,0.3);
  color: #fff;
  border-radius: 9999px;
  font-weight: 600;
  font-size: 0.875rem;
  white-space: nowrap;
  transition: border-color 0.15s;
}

.btn-challenge-ghost:hover { border-color: #fff; }

.resource-section { padding: 1.5rem 0; }

.resource-section h2 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 1rem;
}

.resource-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.75rem;
}

.resource-card {
  padding: 1.125rem;
  background: var(--bg-secondary);
  border: 1px solid var(--border-light);
  border-radius: var(--radius);
  font-size: 0.9375rem;
  font-weight: 500;
  transition: box-shadow 0.15s, background 0.15s;
}

.resource-card:hover {
  background: #fff;
  box-shadow: var(--shadow);
}

.resource-card .badge {
  display: inline-block;
  background: var(--accent);
  color: var(--primary);
  font-size: 0.6875rem;
  font-weight: 700;
  padding: 0.15rem 0.5rem;
  border-radius: 9999px;
  margin-left: 0.375rem;
  vertical-align: middle;
}

/* ===== TAG PAGE ===== */
.tag-header-section {
  padding: 2.5rem 0 0.75rem;
}

.tag-header-section h1 {
  font-size: 2rem;
  font-weight: 800;
}

.tag-header-section h1 strong { color: var(--text); }

.tag-post-count {
  font-size: 1.0625rem;
  color: var(--text-muted);
  margin-top: 0.25rem;
}

.popular-tags-section { padding: 0.75rem 0 2rem; }

.popular-tags-section h2 {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-secondary);
  margin-bottom: 0.75rem;
}

.tags-scroll {
  display: flex;
  gap: 0.625rem;
  overflow-x: auto;
  padding-bottom: 0.5rem;
  -webkit-overflow-scrolling: touch;
}

.tags-scroll::-webkit-scrollbar { height: 4px; }
.tags-scroll::-webkit-scrollbar-track { background: transparent; }
.tags-scroll::-webkit-scrollbar-thumb { background: var(--border); border-radius: 4px; }

.tag-chip {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.5rem 0.875rem;
  background: var(--bg-secondary);
  border: 1px solid var(--border-light);
  border-radius: 9999px;
  font-size: 0.8125rem;
  font-weight: 500;
  white-space: nowrap;
  transition: all 0.15s;
}

.tag-chip:hover { background: #fff; border-color: var(--border); box-shadow: var(--shadow-sm); }

.tag-chip .chip-count {
  font-size: 0.6875rem;
  color: var(--text-muted);
  font-weight: 400;
}

/* ===== FOOTER ===== */
.site-footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border);
  padding: 3rem 0 2rem;
  margin-top: 3rem;
}

.footer-mission {
  margin-bottom: 2rem;
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.7;
  max-width: 800px;
}

.footer-trending h3 {
  font-size: 0.9375rem;
  font-weight: 700;
  margin-bottom: 0.75rem;
}

.trending-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.375rem;
  margin-bottom: 2rem;
}

.trending-tags a {
  padding: 0.35rem 0.75rem;
  background: var(--bg-tertiary);
  border-radius: 9999px;
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all 0.15s;
}

.trending-tags a:hover { background: #D8DAE1; color: var(--text); }

.footer-bottom {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border);
}

.footer-bottom a {
  font-size: 0.8125rem;
  color: var(--text-muted);
  transition: color 0.15s;
}

.footer-bottom a:hover { color: var(--text); }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .article-grid { grid-template-columns: repeat(2, 1fr); }
  .featured-card { grid-template-columns: 1fr; }
  .featured-content { padding: 1.5rem; }
  .featured-image { aspect-ratio: 16/9; }
}

@media (max-width: 768px) {
  .header-nav { display: none; }
  .search-bar { display: none; }
  .hamburger { display: flex; }

  .article-grid { grid-template-columns: 1fr; }
  .curriculum-grid { grid-template-columns: 1fr; }
  .initiatives-grid { grid-template-columns: 1fr; }
  .achievements-grid { grid-template-columns: 1fr; }
  .resource-grid { grid-template-columns: 1fr; }

  .challenge-box { flex-direction: column; text-align: center; }
  .challenge-links { flex-direction: column; width: 100%; }
  .btn-challenge, .btn-challenge-ghost { text-align: center; }

  .donation-hero h1 { font-size: 1.5rem; }
  .amount-btn { padding: 0.75rem 1.5rem; font-size: 1.125rem; }

  .featured-card { border-radius: 0; border-left: none; border-right: none; }
}

@media (max-width: 480px) {
  .container { padding: 0 1rem; }
  .featured-content h2 { font-size: 1.25rem; }
  .section-title { font-size: 1.15rem; }
}
